    ResourceVisibilityContext resource{map,rs,rr,players,roster,techs,types,defines,false};
    ImprovementYieldRules ir;ir.profile=vp;ir.improvements[0].yields[0][0]=7;ir.improvements[1].yields[0][0]=19;ir.routes[0][0]=2;ir.routes[1][0]=3;
    ImprovementYieldState is;is.profile=vp;is.players[5]={};is.teams[9]={};ensure_vp_improvement_yield_profile(is).players[5]={};
    std::map<std::int64_t,std::int64_t> eras{{9,3}};
    ImprovementYieldContext improvements{ir,is,water,resource,eras};VpNatureYieldRules nr;nr.yields[0]={};nr.terrains[0].yields[0][0]=2;nr.plots[2].base[0]=3;VpNatureYieldState ns;ns.players[5]={};
    nr.improvements[0]={};nr.improvements[1]={};
    VpPlotReligionRules rel;rel.yields={0};rel.improvements[0]={};rel.improvements[1]={};
    VpPlayerPlotRules pr;pr.yields[0]={25,13};pr.accomplishments[0]={};pr.accomplishments[1]={};VpPlayerPlotState ps;ps.players[5].matrices[0][2][0]=11;ps.teams[9]={};
    VpPlayerPlotContext player{pr,ps,improvements,nr,ns,movement,rel,9};
    MaintenanceContext units;units.profile=vp;MaintenanceRules ur;ur.profile=vp;VpNatureYieldContext nature{nr,ns,water,movement,cities,units,ur,9};VpPlotYieldContext context{nature,player,5};
    const auto query=[&](bool display=false,bool assumed=false,CityYieldState *c=nullptr){return vp_plot_yield(context,4,0,display,c,assumed);};
    auto q=query();check(q.total==25&&q.nature==5&&q.improvement_yield==9&&q.player_yield==11,"Full VP plot combines helpers and intrinsic route income");
    cities.players[5].golden_age=true;check(query().total==38,"Golden-age threshold sees nature plus improvement and player subtotal");cities.players[5].golden_age=false;
    q=query(true);check(q.total==38&&q.improvement==1&&q.route==1,"Display uses team-known improvement and route independently of actual ones");
    plot.improvement_pillaged=true;check(query(true).total==16&&query(true).improvement==-1,"Actual pillage filters even a stale revealed improvement");plot.improvement_pillaged=false;
    plot.route->pillaged=true;check(query(true).total==35&&query(true).route==-1,"Actual route pillage filters the known route");plot.route->pillaged=false;
    check(query(false,true).total==16&&query(true,true).total==16,"Assume-no-improvement reaches both normal and display fast paths");
    plot.owner=-1;ensure_vp_plot_projection(plot).revealed_types->at(9).owner=-1;check(query(true).player==5&&query().player==-1,"Unowned display falls back to active player; normal query keeps NO_PLAYER without a city");
