    check(query().player==5&&query().total==42,"Effective city supplies unowned tile player and city bonuses");
    plot.yield_city_override=SavedPlotCityReference{5,999};check(vp_plot_effective_city(cities,plot)==nullptr&&query().player==-1,"Stale nonempty city override does not fall back to ordinary owner");
