    plot.yield_city_override=SavedPlotCityReference{};plot.owner=5;plot_bonuses.plot.clear();
    resource.debug_mode=true;check(query(true,true).early==4&&query(true,true).total==251,"Debug display returns cached yield without assumed improvement filtering");
    plot.cached_yields->at(0)=4294967300LL;check(query(true).total==4294967300LL,"Debug plot cache is wide instead of original byte storage");
    plot.potential_city_work=false;check(query(true).early==3&&query(true).total==0,"Potential-work gate precedes debug cache");plot.potential_city_work=true;
    options.entries["CORE_NO_YIELD_ICE"].value=1;plot.feature_type=0;check(query(true).early==2,"No-yield ice option precedes debug cache");plot.feature_type=-1;
    plot.terrain_type=-1;check(query(true).early==1,"NO_TERRAIN is the first full-yield gate");plot.terrain_type=0;resource.debug_mode=false;
    ensure_vp_plot_projection(plot).extra_yields={{0,-30},{0,999}};check(query().extra==-30&&query().total==0,"Ordered plot extras use the first match and only full total clamps to zero");ensure_vp_plot_projection(plot).extra_yields.clear();
    CityYieldReligionBeliefs pantheon;pantheon.religion=0;pantheon.founder=5;pantheon.beliefs={2};ensure_vp_religion_beliefs(pantheon,vp);vp_religion_beliefs(pantheon).pantheon=true;vp_religion_beliefs(pantheon).belief_religion=0;vp_religion_beliefs(pantheon).holy_x=vp_religion_beliefs(pantheon).holy_y=-1;vp_religion_beliefs(pantheon).lookup[2]=1;
    rel.beliefs[2].terrain[0][0]=20;cities.religions={pantheon};options.entries["BALANCE_PERMANENT_PANTHEONS"].value=1;
    cities.players[5].golden_age=true;pr.yields[0].golden_threshold=30;
    q=query(false,true);check(q.permanent_pantheon&&q.improvement==0&&q.pantheon_nature==20&&q.player_yield==11&&q.total==45,"Permanent pantheon wrapper drops assume-no-improvement and adds its income after golden threshold");
    check(vp_plot_yield_fast(context,4,0,false,&city,{},&cities.religions[0],true).improvement==-1,"Explicit fast query still honors assume-no-improvement with a pantheon");
    CityYieldReligionBeliefs major=pantheon;major.religion=1;vp_religion_beliefs(major).pantheon=false;vp_religion_beliefs(major).belief_religion=1;major.founder=7;cities.religions.push_back(major);vp_city_majority_religion(city)=1;
    check(!query().permanent_pantheon,"Majority and personal pantheon sharing lookup value one prevent double counting");vp_religion_beliefs(cities.religions[1]).lookup[2]=2;
    check(query().permanent_pantheon,"Non-one lookup does not suppress a permanent pantheon");
    vp_city_majority_religion(city)=-1;auto selection=VpPlotReligionSelection{nullptr,2};check(!vp_plot_permanent_pantheon(context,city,selection),"Secondary pantheon identity prevents permanent duplicate");
    vp_player_state_religion(cities.players[5])=1;cities.religions[1].beliefs.clear();std::swap(cities.religions[0],cities.religions[1]);
    check(!query().permanent_pantheon,"Earlier state religion with empty belief list stops GetBeliefInPantheon before personal pantheon");
    options.entries["BALANCE_PERMANENT_PANTHEONS"].value=0;cities.players[5].golden_age=false;plot.yield_city=SavedPlotCityReference{};
    ps.players[5].matrices[0][2][0]=4294967300LL;check(query().total==4294967314LL,"Full plot result preserves values above UINT32_MAX");
    ps.players[5].matrices[0][2][0]=INT64_MAX;rejects([&]{query();});auto copy=city;rejects([&]{query(false,false,&copy);});
    MapHeaderObservation header{};header.layout=layout;header.grid={1,1};MapPlotsObservation source{};source.layout=layout;source.plots.emplace_back();auto &raw=source.plots[0];
    raw.fields={{"packed_flags",512},{"terrain_type",-1}};raw.arrays={{"yields",1,{0,4294967300LL}},{"teams",10,{0,0,0,4294967301LL,0,4294967302LL,4294967303LL,0,0,0}}};
    auto projected=project_saved_map(header,source);const auto &restored=projected.cells[0];
    const auto *restored_vp=find_vp_plot_projection(restored);
    check(restored.potential_city_work==true&&restored.cached_yields->at(1)==4294967300LL&&restored_vp&&restored_vp->revealed_types->at(0)==VpPlotRevealedTypes{4294967301LL,4294967302LL,4294967303LL}&&restored_vp->extra_yields.empty(),"VP map extension imports wide revealed values while resetting unsaved extras");
    auto bnw_header=header;auto bnw_source=source;
    bnw_header.layout=GameStateLayout::expansion2_version1;bnw_source.layout=bnw_header.layout;
    check(!find_vp_plot_projection(project_saved_map(bnw_header,bnw_source).cells.at(0)),
          "BNW map projection does not create VP plot state");
    raw.arrays.push_back(raw.arrays[0]);rejects([&]{project_saved_map(header,source);});raw.arrays.pop_back();raw.arrays[1].columns=1;rejects([&]{project_saved_map(header,source);});
